import React, { useEffect, useState } from 'react';
import { getSessions } from '../services/api';

export default function Dashboard({ user }){
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(()=>{
    const fetchSessions = async ()=> {
      try {
        const data = await getSessions(user.id);
        setSessions(data);
      } catch(e) {
        console.error('Error fetching sessions:', e);
      }
      setLoading(false);
    };
    fetchSessions();
  }, [user.id]);

  return (
    <div style={{padding: 12}}>
      <h3>Session Dashboard</h3>
      <p>User: <strong>{user.username}</strong></p>
      {loading ? (
        <div>Loading sessions...</div>
      ) : sessions.length === 0 ? (
        <div>No sessions yet. Start a new session from the Home page.</div>
      ) : (
        <table style={{width:'100%', borderCollapse: 'collapse'}}>
          <thead>
            <tr style={{borderBottom:'2px solid #06f'}}>
              <th style={{textAlign:'left', padding:8}}>ID</th>
              <th style={{textAlign:'left', padding:8}}>Start Time</th>
              <th style={{textAlign:'left', padding:8}}>End Time</th>
              <th style={{textAlign:'left', padding:8}}>Metrics</th>
            </tr>
          </thead>
          <tbody>
            {sessions.map(s => {
              const metrics = s.metrics ? JSON.parse(s.metrics) : [];
              return (
                <tr key={s.id} style={{borderBottom:'1px solid #ddd'}}>
                  <td style={{padding:8}}>{s.id}</td>
                  <td style={{padding:8}}>{s.start_time ? new Date(s.start_time).toLocaleString() : 'N/A'}</td>
                  <td style={{padding:8}}>{s.end_time ? new Date(s.end_time).toLocaleString() : 'N/A'}</td>
                  <td style={{padding:8}}>{metrics.length} points</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}
